// Parses durations used in ledger export schedules.
const UNIT_MS = {
	ms: 1,
	s: 1000,
	m: 60 * 1000,
	h: 60 * 60 * 1000,
};

export function parseDuration(text) {
	const match = /^(\d+(?:\.\d+)?)(ms|s|m|h)$/.exec(text.trim());
	if (!match) {
		throw new Error(`Unsupported duration: ${text}`);
	}
	const [, amount, unit] = match;
	const value = Number(amount) * UNIT_MS[unit];
	if (!Number.isFinite(value) || value <= 0) {
		throw new Error(`Duration must be positive: ${text}`);
	}
	return Math.round(value);
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { parseDuration } from '../src/duration.js';

test('parses seconds', () => {
	assert.equal(parseDuration('30s'), 30000);
});

test('parses minutes, hours and fractions', () => {
	assert.equal(parseDuration('5m'), 300000);
	assert.equal(parseDuration('1.5h'), 5400000);
	assert.equal(parseDuration('250ms'), 250);
});

test('rejects zero and unknown units', () => {
	assert.throws(() => parseDuration('0s'));
	assert.throws(() => parseDuration('3d'));
});

// Token bucket: allows short bursts while holding the long-run rate to `ratePerSecond`.
export class RateLimiter {
	constructor({ capacity, ratePerSecond, now = () => Date.now(), sleep = ms => new Promise(resolve => setTimeout(resolve, ms)) }) {
		this.capacity = capacity;
		this.ratePerSecond = ratePerSecond;
		this.tokens = capacity;
		this.lastRefill = now();
		this.pausedUntil = 0;
		this.now = now;
		this.sleep = sleep;
	}

	refill() {
		const current = this.now();
		const elapsedSeconds = (current - this.lastRefill) / 1000;
		this.tokens = Math.min(this.capacity, this.tokens + elapsedSeconds * this.ratePerSecond);
		this.lastRefill = current;
	}

	async take() {
		for (;;) {
			const pause = this.pausedUntil - this.now();
			if (pause > 0) {
				await this.sleep(pause);
				continue;
			}
			this.refill();
			if (this.tokens >= 1) {
				this.tokens -= 1;
				return;
			}
			const waitMs = ((1 - this.tokens) / this.ratePerSecond) * 1000;
			await this.sleep(Math.ceil(waitMs));
		}
	}

	pauseFor(ms) {
		this.pausedUntil = Math.max(this.pausedUntil, this.now() + ms);
		this.tokens = 0;
	}
}

// Minimal client for the ledger HTTP API.
import { RateLimiter } from './rateLimiter.js';

export class ApiClient {
	constructor(baseUrl, fetchImpl = fetch, limiter = new RateLimiter({ capacity: 5, ratePerSecond: 2 })) {
		this.baseUrl = baseUrl;
		this.fetchImpl = fetchImpl;
		this.limiter = limiter;
	}

	async request(path) {
		await this.limiter.take();
		const response = await this.fetchImpl(`${this.baseUrl}${path}`);
		if (response.status === 429) {
			const retryAfterSeconds = Number(response.headers.get('Retry-After') ?? '1');
			this.limiter.pauseFor(retryAfterSeconds * 1000);
			return this.request(path);
		}
		return response;
	}

	async getBalance(accountId) {
		const response = await this.request(`/accounts/${accountId}/balance`);
		if (!response.ok) {
			throw new Error(`Balance request failed: ${response.status}`);
		}
		return response.json();
	}

	async listTransactions(accountId, page = 1) {
		const response = await this.request(`/accounts/${accountId}/transactions?page=${page}`);
		if (!response.ok) {
			throw new Error(`Transactions request failed: ${response.status}`);
		}
		return response.json();
	}
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { RateLimiter } from '../src/rateLimiter.js';

function fakeClock() {
	let time = 0;
	return { now: () => time, sleep: async ms => { time += ms; } };
}

test('allows a burst up to capacity, then paces requests', async () => {
	const clock = fakeClock();
	const limiter = new RateLimiter({ capacity: 3, ratePerSecond: 2, ...clock });
	for (let i = 0; i < 3; i++) {
		await limiter.take();
	}
	assert.equal(clock.now(), 0);
	await limiter.take();
	assert.equal(clock.now(), 500);
});

test('pauseFor drains the bucket and waits out Retry-After', async () => {
	const clock = fakeClock();
	const limiter = new RateLimiter({ capacity: 3, ratePerSecond: 2, ...clock });
	limiter.pauseFor(2000);
	await limiter.take();
	assert.ok(clock.now() >= 2000);
});
